"""Collect public post responses generated by Douyin's own browser page."""
import asyncio
from urllib.parse import quote
from utils.automation_provider import async_playwright
from myUtils.automation_context_factory import create_context_with_policy


async def collect_browser_posts(storage_state, sec_user_id):
    queue = asyncio.Queue()
    async with async_playwright() as pw:
        browser, context, _, _ = await create_context_with_policy(
            pw, platform="douyin", account_id=None, headless=True,
            storage_state=storage_state, force_ephemeral=True, disable_proxy=True,
        )
        try:
            page = await context.new_page()
            async def capture(response):
                if "/aweme/v1/web/aweme/post/" not in response.url:
                    return
                try:
                    payload = await response.json()
                    if response.status == 200 and payload.get("status_code") == 0:
                        await queue.put(payload)
                except Exception:
                    pass
            page.on("response", capture)
            await page.goto("https://www.douyin.com/user/" + quote(sec_user_id, safe=""), wait_until="domcontentloaded", timeout=30000)
            items = {}
            for _ in range(100):
                try:
                    payload = await asyncio.wait_for(queue.get(), timeout=20)
                except asyncio.TimeoutError as exc:
                    raise RuntimeError("抖音浏览器未返回有效作品数据，请检查登录或平台验证") from exc
                for item in payload.get("aweme_list") or []:
                    if item.get("aweme_id"):
                        items[item["aweme_id"]] = item
                if not payload.get("has_more"):
                    return {"status_code": 0, "aweme_list": list(items.values()), "has_more": 0}
                await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
            raise RuntimeError("作品分页超过采集上限，未完成全部采集")
        finally:
            await context.close()
            if browser:
                await browser.close()


async def resolve_browser_self_sec_uid(storage_state, expected_user_id):
    """Read the authenticated user's own profile, never a search-result user."""
    async with async_playwright() as pw:
        browser, context, _, _ = await create_context_with_policy(
            pw, platform="douyin", account_id=None, headless=True,
            storage_state=storage_state, force_ephemeral=True, disable_proxy=True,
        )
        try:
            page = await context.new_page()
            async with page.expect_response(lambda response: "/aweme/v1/web/user/profile/self/" in response.url and response.status == 200, timeout=20000) as pending:
                await page.goto("https://www.douyin.com/user/self", wait_until="domcontentloaded", timeout=30000)
            payload = await (await pending.value).json()
            user = payload.get("user") or payload.get("user_info") or {}
            identifiers = {str(user[key]) for key in ("unique_id", "short_id") if user.get(key) and str(user[key]) != "0"}
            if identifiers and str(expected_user_id) not in identifiers:
                return None
            sec_uid = user.get("sec_uid")
            return sec_uid if isinstance(sec_uid, str) and sec_uid.startswith("MS4") else None
        finally:
            await context.close()
            if browser:
                await browser.close()
